To control a laser system using an Arduino Nano with four stepper motors (X, Y, Z, and focus lens), you'll need to utilize a stepper motor driver (like A4988 or DRV8825) for each motor. Below is a simple structure for your Arduino sketch. This code will illustrate how to initialize the motors and move them to desired positions.

### Required Libraries
Make sure to include the AccelStepper library, which simplifies the control of stepper motors.

```cpp
#include <AccelStepper.h>

// Define stepper motor connections and motor interface type
#define X_STEP_PIN 3
#define X_DIR_PIN 4
#define Y_STEP_PIN 5
#define Y_DIR_PIN 6
#define Z_STEP_PIN 7
#define Z_DIR_PIN 8
#define FOCUS_STEP_PIN 9
#define FOCUS_DIR_PIN 10

// Create instances of the AccelStepper class
AccelStepper stepperX(1, X_STEP_PIN, X_DIR_PIN);
AccelStepper stepperY(1, Y_STEP_PIN, Y_DIR_PIN);
AccelStepper stepperZ(1, Z_STEP_PIN, Z_DIR_PIN);
AccelStepper stepperFocus(1, FOCUS_STEP_PIN, FOCUS_DIR_PIN);

// Motor settings
const int maxSpeed = 1000; // Max speed for the motors
const int acceleration = 500; // Acceleration rate

void setup() {
  // Set the maximum speed and acceleration for each motor
  stepperX.setMaxSpeed(maxSpeed);
  stepperX.setAcceleration(acceleration);

  stepperY.setMaxSpeed(maxSpeed);
  stepperY.setAcceleration(acceleration);

  stepperZ.setMaxSpeed(maxSpeed);
  stepperZ.setAcceleration(acceleration);

  stepperFocus.setMaxSpeed(maxSpeed);
  stepperFocus.setAcceleration(acceleration);

  // Initialize Serial communication for monitoring
  Serial.begin(9600);
}

void loop() {
  // Example movements
  moveToPosition(stepperX, 1000); // Move X to 1000 steps
  moveToPosition(stepperY, 500);  // Move Y to 500 steps
  moveToPosition(stepperZ, 300);  // Move Z to 300 steps
  moveToPosition(stepperFocus, 200); // Focus lens adjustment

  delay(5000); // Wait for a while before repeating the movements
}

void moveToPosition(AccelStepper& stepper, int position) {
  stepper.moveTo(position);
  while(stepper.distanceToGo() != 0) {
    stepper.run();
  }
}
```

### Code Explanation
