```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string filename;
    string searchWord;

    cout << "Enter the name of the file: ";
    cin >> filename;

    cout << "Enter the word to search for: ";
    cin >> searchWord;

    ifstream file(filename);
    if (!file.is_open()) {
        cerr << "Error opening file" << endl;
        return 1;
    }

    string line;
    int count = 0;
