Here’s a sample implementation of the Stoer-Wagner algorithm in Swift. This algorithm is used to find the minimum cut in a weighted, undirected graph.

```swift
import Foundation

class Graph {
    private var adjacencyMatrix: [[Int]]
    private var vertices: Int

    init(vertices: Int) {
        self.vertices = vertices
        self.adjacencyMatrix = Array(repeating: Array(repeating: 0, count: vertices), count: vertices)
    }

    func addEdge(from source: Int, to destination: Int, weight: Int) {
        adjacencyMatrix[source][destination] += weight
        adjacencyMatrix[destination][source] += weight
    }

    func stoerWagner() -> Int {
        var minCut = Int.max
        var vertices = Array(0..<self.vertices)

        while vertices.count > 1 {
            let (lastAdded, lastWeight) = aPhase(&vertices)
            if lastWeight < minCut {
                minCut = lastWeight
            }
            mergeVertices(lastAdded, &vertices)
        }
        return minCut
    }

    private func aPhase(_ vertices: inout [Int]) -> (Int, Int) {
        var weights = Array(repeating: 0, count: self.vertices)
        var added = Array(repeating: false, count: self.vertices)

        var lastAdded = -1
        var lastWeight = 0

        for _ in 0..<vertices.count {
            var maxWeight = -1
            var nextVertex = -1

            for v in vertices {
                if !added[v] {
                    weights[v] += adjacencyMatrix[vertices[0]][v]
                    if weights[v] > maxWeight {
                        maxWeight = weights[v]
                        nextVertex = v
                    }
                }
            }

            if nextVertex == -1 {
                break
            }

            added[nextVertex] = true
            lastAdded = nextVertex
            lastWeight = maxWeight

            // Adjust weights for the next iteration
            for v in vertices {
                if !added[v] {
                    weights[v] += adjacencyMatrix[nextVertex][v]
                }
            }
        }
        return (lastAdded, lastWeight)
    }

    private func mergeVertices(_ v: Int, _ vertices: inout [Int]) {
        let lastVertex = vertices.last!
        vertices.removeLast()

        for i in vertices {
            adjacencyMatrix[i][lastVertex] += adjacencyMatrix[i][v]
            adjacencyMatrix[v][i] = 0 // Remove edge
        }
    }
}

// Example Usage
let graph = Graph(vertices: 4)
graph.addEdge(from: 0, to: 1, weight: 3)
graph.addEdge(from: 0, to: 2, weight: 5)
graph.addEdge(from: 1, to: 2, weight: 2)
graph.addEdge(from: 1, to: 3, weight: 6)
graph.addEdge(from: 2, to: 3, weight: 4)

let minCutValue = graph.stoerWagner()
print("The minimum cut value is: \(minCutValue)")
```

### Summary
1. **Graph Class**: Defines the graph with an adjacency matrix.
2. **Add Edge**: Method to add edges and their weights to the graph.
3. **Stoer-Wagner Method**: Main method to compute the minimum cut.
4. **aPhase Method**: Performs the A-phase to collect weights for vertices.
5. **Merge Vertices**: Merges vertices after identifying the minimum cut.

This implementation provides a clear structure for calculating the minimum cut using the Stoer-Wagner algorithm in Swift.

