```go
package main

import (
	"fmt"
	"log"
	"math"
	"os"
	"strconv"
)

// isPrime checks whether a number is prime or not.
func isPrime(num int) bool {
	if num < 2 {
		return false
	}
	for i := 2; i <= int(math.Sqrt(float64(num))); i++ {
		if num%i == 0 {
			return false
		}
	}
	return true
}

// getPrimes returns the first n prime numbers.
func getPrimes(n int) []int {
	primes := []int{}
	num := 2 // The first prime number
	for len(primes) < n {
		if isPrime(num) {
			primes = append(primes, num)
		}
		num++
	}
	return primes
}

func main() {
	if len(os.Args) != 2 {
		log.Fatalf("Usage: %s <n>", os.Args[0])
	}

	n, err := strconv.Atoi(os.Args[1])
	if err != nil || n <= 0 {
		log.Fatalf("Please provide a valid positive integer for n")
