In C programming, handling errors effectively is crucial for writing robust and maintainable code. There are several approaches to return error information from functions. Here are the most common methods:

### 1. Return Error Codes
One of the most common ways to handle errors in C is to return an error code. The function returns an integer (or other types) where a specific value indicates success, and others indicate different errors.

```c
#include <stdio.h>

#define SUCCESS 0
#define ERROR_INVALID_INPUT -1
#define ERROR_FILE_NOT_FOUND -2

int processData(int input) {
    if (input < 0) {
        return ERROR_INVALID_INPUT; // Return error code for invalid input
    }
    // Logic for processing data...
    return SUCCESS; // Return success code
}

int main() {
    int result = processData(-1);
    if (result < 0) {
        // Handle error based on error code
        if (result == ERROR_INVALID_INPUT) {
            printf("Error: Invalid input!\n");
        }
    }
    return 0;
}
```

### 2. Use `errno`
The C standard library defines a global variable `errno` that is set to an error code whenever a library function fails. You can set `errno` yourself for custom errors.

```c
#include <stdio.h>
#include <errno.h>

#define CUSTOM_ERROR 100 // Custom error definition

int processData(int input) {
    if (input < 0) {
        errno = CUSTOM_ERROR; // Set custom error code
        return -1; // Indicate an error occurred
    }
    // Logic for processing data...
    return 0; // Success
}

int main() {
    if (processData(-1) < 0) {
        perror("Process failed"); // Print error message based on errno
    }
    return 0;
}
```

### 3. Use Output Parameters
Another method is to use output parameters for returning multiple values, including error information.

```c
#include <stdio.h>

int processData(int input, int *result) {
    if (input < 0) {
        return -1; // Return error code
    }
    *result = input * 2; // Example processing
    return 0; // Success
}

int main() {
    int output;
    if (processData(-1, &output) < 0) {
        printf("Error: Invalid input!\n");
    } else {
        printf("Result: %d\n", output);
    }
    return 0;
}
```

### 4. Use Structs for Detailed Error Information
You can define a struct to encapsulate both the result and error information.

```c
#include <stdio.h>

typedef struct {
    int value;
    int errorCode;
} Result;

Result processData(int input) {
    Result res;
    if (input < 0) {
        res.value = 0;
        res.errorCode = -1; // Indicate an error occurred
    } else {
        res.value = input * 2; // Example processing
        res.errorCode = 0; // Success
    }
    return res;
}

int main() {
    Result res = processData(-1);
    if (res.errorCode < 0) {
        printf("Error: Invalid input!\n");
    } else {
        printf("Result: %d\n", res.value);
    }
    return 0;
}
```

### Best Practices
- Always document the possible return values of your functions, including error codes.
- Make sure to use consistent error codes across your application.
- Consider using `errno` for standard library functions when integrating your code with the standard library.

By adopting one (or a combination) of these approaches, you can effectively handle errors in your C programs.

