Here's a simple implementation of a console-based Tic Tac Toe game in Python based on the specified requirements:

```python
# Tic Tac Toe Game

def initialize_board():
    return [[" " for _ in range(3)] for _ in range(3)]

def print_board(board):
    print("Current board:")
    for row in board:
        print("|".join(row))
        print("-" * 5)

def check_winner(board):
    for row in board:
        if row[0] == row[1] == row[2] != " ":
            return row[0]

    for col in range(3):
        if board[0][col] == board[1][col] == board[2][col] != " ":
            return board[0][col]

    if board[0][0] == board[1][1] == board[2][2] != " ":
        return board[0][0]

    if board[0][2] == board[1][1] == board[2][0] != " ":
        return board[0][2]

    return None

def is_draw(board):
    for row in board:
        if " " in row:
            return False
    return True

def get_valid_input(player):
    while True:
        try:
            move = int(input(f"Player {player}, enter your move (1-9): ")) - 1
            if move < 0 or move > 8:
                print("Invalid input. Please enter a number from 1 to 9.")
                continue
            return move
        except ValueError:
            print("Invalid input. Please enter a valid number.")

def place_move(board, move, player):
    row = move // 3
    col = move % 3
    if board[row][col] != " ":
        print("Spot already filled! Try again.")
        return False
    board[row][col] = player
    return True

def tic_tac_toe():
    board = initialize_board()
    current_player = "X"

    while True:
        print_board(board)
        move = get_valid_input(current_player)

        if not place_move(board, move, current_player):
            continue

        if winner := check_winner(board):
            print_board(board)
            print(f"Player {winner} wins!")
            break

        if is_draw(board):
            print_board(board)
            print("It's a draw!")
            break

        # Switch players
        current_player = "O" if current_player == "X" else "X"

if __name__ == "__main__":
    tic_tac_toe()
```

### Key Points:
- The game board is represented by a 2D list (3x3 grid).
- Players take turns to place their symbols (X or O).
- The game checks for a winner or a draw after each turn.
- Input validation is implemented to ensure moves are within the permissible range and not on filled spots.
- The current state of the board is printed after each turn for players to see. 

You can run this Python code in any environment that supports Python to play the game.

